"""Portable, self-contained public POLARIS project emblem for PDF exports.

Vercel's Python serverless function may exclude files in the public/ static
directory. Embed the exact site-approved PNG so PDF exports never depend on
the presence of the web asset directory at runtime.
"""
from __future__ import annotations
from base64 import b64decode
from io import BytesIO
from pathlib import Path

LOGO_FILE = Path(__file__).resolve().parents[1] / "public" / "polaris-mission-patch-v2.png"
LOGO_NAME = "polaris-mission-patch-v2.png"
_LOGO_BASE64 = """"""
LOGO_PNG = b64decode("".join(_LOGO_BASE64.split()))
assert LOGO_PNG[:8] == bytes.fromhex("89504e470d0a1a0a"), "Damaged embedded POLARIS logo"


def draw_polaris_pdf_logo(canvas, x: float, y: float, size: float) -> None:
    """Draw the public-site logo without accessing the filesystem."""
    from reportlab.lib.utils import ImageReader
    canvas.drawImage(ImageReader(BytesIO(LOGO_PNG)), x, y,
                     width=size, height=size, preserveAspectRatio=True,
                     anchor="c", mask="auto")
